17	package com.google.zxing.common;
18	
19	import java.util.List;
20	
21	/**
22	 * <p>Encapsulates the result of decoding a matrix of bits. This typically
23	 * applies to 2D barcode formats. For now it contains the raw bytes obtained,
24	 * as well as a String interpretation of those bytes, if applicable.</p>
25	 *
26	 * @author Sean Owen
27	 */
28	public final class DecoderResult {
29	
30	  private final byte[] rawBytes;
31	  private int numBits;
32	  private final String text;
33	  private final List<byte[]> byteSegments;
34	  private final String ecLevel;
35	  private Integer errorsCorrected;
36	  private Integer erasures;
37	  private Object other;
38	  private Boolean readerInit;
39	  private final int structuredAppendParity;
40	  private final int structuredAppendSequenceNumber;
41	  private final int symbologyModifier;
42	
43	  public DecoderResult(byte[] rawBytes,
44	                       String text,
45	                       List<byte[]> byteSegments,
46	                       String ecLevel) {
47	    this(rawBytes, text, byteSegments, ecLevel, -1, -1, 0);
48	  }
49	
50	  public DecoderResult(byte[] rawBytes,
51	                       String text,
52	                       List<byte[]> byteSegments,
53	                       String ecLevel,
54	                       int symbologyModifier) {
55	    this(rawBytes, text, byteSegments, ecLevel, -1, -1, symbologyModifier);
56	  }
57	
58	  public DecoderResult(byte[] rawBytes,
59	                       String text,
60	                       List<byte[]> byteSegments,
61	                       String ecLevel,
62	                       int saSequence,
63	                       int saParity) {
64	    this(rawBytes, text, byteSegments, ecLevel, saSequence, saParity, 0);
65	  }
66	
67	  public DecoderResult(byte[] rawBytes,
68	                       String text,
69	                       List<byte[]> byteSegments,
70	                       String ecLevel,
71	                       int saSequence,
72	                       int saParity,
73	                       int symbologyModifier) {
74	    this.rawBytes = rawBytes;
75	    this.numBits = rawBytes == null ? 0 : 8 * rawBytes.length;
76	    this.text = text;
77	    this.byteSegments = byteSegments;
78	    this.ecLevel = ecLevel;
79	    this.structuredAppendParity = saParity;
80	    this.structuredAppendSequenceNumber = saSequence;
81	    this.symbologyModifier = symbologyModifier;
82	  }
83	
84	  /**
85	   * @return raw bytes representing the result, or {@code null} if not applicable
86	   */
87	  public byte[] getRawBytes() {
88	    return rawBytes;
89	  }
90	
91	  /**
