17	package com.google.zxing.common;
18	
19	import com.google.zxing.NotFoundException;
20	
21	/**
22	 * Implementations of this class can, given locations of finder patterns for a QR code in an
23	 * image, sample the right points in the image to reconstruct the QR code, accounting for
24	 * perspective distortion. It is abstracted since it is relatively expensive and should be allowed
25	 * to take advantage of platform-specific optimized implementations, like Sun's Java Advanced
26	 * Imaging library, but which may not be available in other environments such as J2ME, and vice
27	 * versa.
28	 *
29	 * The implementation used can be controlled by calling {@link #setGridSampler(GridSampler)}
30	 * with an instance of a class which implements this interface.
31	 *
32	 * @author Sean Owen
33	 */
34	public abstract class GridSampler {
35	
36	  private static GridSampler gridSampler = new DefaultGridSampler();
37	
38	  /**
39	   * Sets the implementation of GridSampler used by the library. One global
40	   * instance is stored, which may sound problematic. But, the implementation provided
41	   * ought to be appropriate for the entire platform, and all uses of this library
42	   * in the whole lifetime of the JVM. For instance, an Android activity can swap in
43	   * an implementation that takes advantage of native platform libraries.
44	   *
45	   * @param newGridSampler The platform-specific object to install.
46	   */
47	  public static void setGridSampler(GridSampler newGridSampler) {
48	    gridSampler = newGridSampler;
49	  }
50	
51	  /**
52	   * @return the current implementation of GridSampler
53	   */
54	  public static GridSampler getInstance() {
55	    return gridSampler;
56	  }
57	
58	  /**
59	   * Samples an image for a rectangular matrix of bits of the given dimension. The sampling
60	   * transformation is determined by the coordinates of 4 points, in the original and transformed
61	   * image space.
62	   *
63	   * @param image image to sample
64	   * @param dimensionX width of {@link BitMatrix} to sample from image
65	   * @param dimensionY height of {@link BitMatrix} to sample from image
66	   * @param p1ToX point 1 preimage X
67	   * @param p1ToY point 1 preimage Y
68	   * @param p2ToX point 2 preimage X
69	   * @param p2ToY point 2 preimage Y
70	   * @param p3ToX point 3 preimage X
71	   * @param p3ToY point 3 preimage Y
72	   * @param p4ToX point 4 preimage X
73	   * @param p4ToY point 4 preimage Y
74	   * @param p1FromX point 1 image X
75	   * @param p1FromY point 1 image Y
76	   * @param p2FromX point 2 image X
77	   * @param p2FromY point 2 image Y
78	   * @param p3FromX point 3 image X
79	   * @param p3FromY point 3 image Y
80	   * @param p4FromX point 4 image X
81	   * @param p4FromY point 4 image Y
82	   * @return {@link BitMatrix} representing a grid of points sampled from the image within a region
83	   *   defined by the "from" parameters
84	   * @throws NotFoundException if image can't be sampled, for example, if the transformation defined
85	   *   by the given points is invalid or results in sampling outside the image boundaries
86	   */
87	  public abstract BitMatrix sampleGrid(BitMatrix image,
88	                                       int dimensionX,
89	                                       int dimensionY,
90	                                       float p1ToX, float p1ToY,
91	                                       float p2ToX, float p2ToY,
92	                                       float p3ToX, float p3ToY,
93	                                       float p4ToX, float p4ToY,
94	                                       float p1FromX, float p1FromY,
95	                                       float p2FromX, float p2FromY,
96	                                       float p3FromX, float p3FromY,
97	                                       float p4FromX, float p4FromY) throws NotFoundException;
98	
99	  public abstract BitMatrix sampleGrid(BitMatrix image,
100	                                       int dimensionX,
101	                                       int dimensionY,
102	                                       PerspectiveTransform transform) throws NotFoundException;
103	
104	  /**
105	   * <p>Checks a set of points that have been transformed to sample points on an image against
106	   * the image's dimensions to see if the point are even within the image.</p>
107	   *
108	   * <p>This method will actually "nudge" the endpoints back onto the image if they are found to be
109	   * barely (less than 1 pixel) off the image. This accounts for imperfect detection of finder
110	   * patterns in an image where the QR Code runs all the way to the image border.</p>
111	   *
112	   * <p>For efficiency, the method will check points from either end of the line until one is found
113	   * to be within the image. Because the set of points are assumed to be linear, this is valid.</p>
114	   *
115	   * @param image image into which the points should map
116	   * @param points actual points in x1,y1,...,xn,yn form
117	   * @throws NotFoundException if an endpoint is lies outside the image boundaries
118	   */
119	  protected static void checkAndNudgePoints(BitMatrix image,
120	                                            float[] points) throws NotFoundException {
121	    int width = image.getWidth();
122	    int height = image.getHeight();
123	    // Check and nudge points from start until we see some that are OK:
124	    boolean nudged = true;
125	    int maxOffset = points.length - 1; // points.length must be even
126	    for (int offset = 0; offset < maxOffset && nudged; offset += 2) {
127	      int x = (int) points[offset];
128	      int y = (int) points[offset + 1];
129	      if (x < -1 || x > width || y < -1 || y > height) {
130	        throw NotFoundException.getNotFoundInstance();
131	      }
132	      nudged = false;
133	      if (x == -1) {
134	        points[offset] = 0.0f;
135	        nudged = true;
136	      } else if (x == width) {
137	        points[offset] = width - 1;
138	        nudged = true;
139	      }
140	      if (y == -1) {
141	        points[offset + 1] = 0.0f;
142	        nudged = true;
143	      } else if (y == height) {
144	        points[offset + 1] = height - 1;
145	        nudged = true;
146	      }
147	    }
148	    // Check and nudge points from end:
149	    nudged = true;
150	    for (int offset = points.length - 2; offset >= 0 && nudged; offset -= 2) {
151	      int x = (int) points[offset];
152	      int y = (int) points[offset + 1];
153	      if (x < -1 || x > width || y < -1 || y > height) {
154	        throw NotFoundException.getNotFoundInstance();
155	      }
156	      nudged = false;
157	      if (x == -1) {
158	        points[offset] = 0.0f;
159	        nudged = true;
160	      } else if (x == width) {
161	        points[offset] = width - 1;
162	        nudged = true;
163	      }
164	      if (y == -1) {
165	        points[offset + 1] = 0.0f;
166	        nudged = true;
167	      } else if (y == height) {
168	        points[offset + 1] = height - 1;
169	        nudged = true;
170	      }
171	    }
172	  }
173	
174	}
