17	package com.google.zxing.qrcode;
18	
19	import com.google.zxing.BarcodeFormat;
20	import com.google.zxing.EncodeHintType;
21	import com.google.zxing.Writer;
22	import com.google.zxing.WriterException;
23	import com.google.zxing.common.BitMatrix;
24	import com.google.zxing.qrcode.encoder.ByteMatrix;
25	import com.google.zxing.qrcode.decoder.ErrorCorrectionLevel;
26	import com.google.zxing.qrcode.encoder.Encoder;
27	import com.google.zxing.qrcode.encoder.QRCode;
28	
29	import java.util.Map;
30	
31	/**
32	 * This object renders a QR Code as a BitMatrix 2D array of greyscale values.
33	 *
34	 * @author dswitkin@google.com (Daniel Switkin)
35	 */
36	public final class QRCodeWriter implements Writer {
37	
38	  private static final int QUIET_ZONE_SIZE = 4;
39	
40	  @Override
41	  public BitMatrix encode(String contents, BarcodeFormat format, int width, int height)
42	      throws WriterException {
43	
44	    return encode(contents, format, width, height, null);
45	  }
46	
47	  @Override
48	  public BitMatrix encode(String contents,
49	                          BarcodeFormat format,
50	                          int width,
51	                          int height,
52	                          Map<EncodeHintType,?> hints) throws WriterException {
53	
54	    if (contents.isEmpty()) {
55	      throw new IllegalArgumentException("Found empty contents");
56	    }
57	
58	    if (format != BarcodeFormat.QR_CODE) {
59	      throw new IllegalArgumentException("Can only encode QR_CODE, but got " + format);
60	    }
61	
62	    if (width < 0 || height < 0) {
63	      throw new IllegalArgumentException("Requested dimensions are too small: " + width + 'x' +
64	          height);
65	    }
66	
67	    ErrorCorrectionLevel errorCorrectionLevel = ErrorCorrectionLevel.L;
68	    int quietZone = QUIET_ZONE_SIZE;
69	    if (hints != null) {
70	      if (hints.containsKey(EncodeHintType.ERROR_CORRECTION)) {
71	        errorCorrectionLevel = ErrorCorrectionLevel.valueOf(hints.get(EncodeHintType.ERROR_CORRECTION).toString());
72	      }
73	      if (hints.containsKey(EncodeHintType.MARGIN)) {
74	        quietZone = Integer.parseInt(hints.get(EncodeHintType.MARGIN).toString());
75	      }
76	    }
77	
78	    QRCode code = Encoder.encode(contents, errorCorrectionLevel, hints);
79	    return renderResult(code, width, height, quietZone);
80	  }
81	
82	  /**
83	   * Renders the given {@link QRCode} as a {@link BitMatrix}, scaling the
84	   * same to be compliant with the provided dimensions.
85	   *
86	   * <p>If no scaling is required, both {@code width} and {@code height}
87	   * arguments should be non-positive numbers.
88	   *
89	   * @param code {@code QRCode} to be adapted as a {@code BitMatrix}
90	   * @param width desired width for the {@code QRCode} (in pixel units)
91	   * @param height desired height for the {@code QRCode} (in pixel units)
92	   * @param quietZone the size of the QR quiet zone (in pixel units)
93	   * @return {@code BitMatrix} instance
94	   *
95	   * @throws IllegalStateException if {@code code} does not have
96	   *      a {@link QRCode#getMatrix() Matrix}
97	   *
98	   * @throws NullPointerException if {@code code} is {@code null}
99	   */
100	  public static BitMatrix renderResult(QRCode code, int width, int height, int quietZone) {
101	    // Note that the input matrix uses 0 == white, 1 == black, while the output matrix uses
102	    // 0 == black, 255 == white (i.e. an 8 bit greyscale bitmap).
103	    ByteMatrix input = code.getMatrix();
104	    if (input == null) {
105	      throw new IllegalStateException();
106	    }
107	    int inputWidth = input.getWidth();
108	    int inputHeight = input.getHeight();
109	    int qrWidth = inputWidth + (quietZone * 2);
110	    int qrHeight = inputHeight + (quietZone * 2);
111	    int outputWidth = Math.max(width, qrWidth);
112	    int outputHeight = Math.max(height, qrHeight);
113	
114	    int multiple = Math.min(outputWidth / qrWidth, outputHeight / qrHeight);
115	    // Padding includes both the quiet zone and the extra white pixels to accommodate the requested
116	    // dimensions. For example, if input is 25x25 the QR will be 33x33 including the quiet zone.
117	    // If the requested size is 200x160, the multiple will be 4, for a QR of 132x132. These will
118	    // handle all the padding from 100x100 (the actual QR) up to 200x160.
119	    int leftPadding = (outputWidth - (inputWidth * multiple)) / 2;
120	    int topPadding = (outputHeight - (inputHeight * multiple)) / 2;
121	
122	    BitMatrix output = new BitMatrix(outputWidth, outputHeight);
123	
124	    for (int inputY = 0, outputY = topPadding; inputY < inputHeight; inputY++, outputY += multiple) {
125	      // Write the contents of this row of the barcode
126	      for (int inputX = 0, outputX = leftPadding; inputX < inputWidth; inputX++, outputX += multiple) {
127	        if (input.get(inputX, inputY) == 1) {
128	          output.setRegion(outputX, outputY, multiple, multiple);
129	        }
130	      }
131	    }
132	
133	    return output;
134	  }
135	}
