17	package com.google.zxing.qrcode;
18	
19	import com.google.zxing.BarcodeFormat;
20	import com.google.zxing.BinaryBitmap;
21	import com.google.zxing.ChecksumException;
22	import com.google.zxing.DecodeHintType;
23	import com.google.zxing.FormatException;
24	import com.google.zxing.NotFoundException;
25	import com.google.zxing.Reader;
26	import com.google.zxing.Result;
27	import com.google.zxing.ResultMetadataType;
28	import com.google.zxing.ResultPoint;
29	import com.google.zxing.common.BitMatrix;
30	import com.google.zxing.common.DecoderResult;
31	import com.google.zxing.common.DetectorResult;
32	import com.google.zxing.qrcode.decoder.Decoder;
33	import com.google.zxing.qrcode.decoder.QRCodeDecoderMetaData;
34	import com.google.zxing.qrcode.detector.Detector;
35	
36	import java.util.List;
37	import java.util.Map;
38	
39	/**
40	 * This implementation can detect and decode QR Codes in an image.
41	 *
42	 * @author Sean Owen
43	 */
44	public class QRCodeReader implements Reader {
45	
46	  private static final ResultPoint[] NO_POINTS = new ResultPoint[0];
47	
48	  private final Decoder decoder = new Decoder();
49	
50	  protected final Decoder getDecoder() {
51	    return decoder;
52	  }
53	
54	  /**
55	   * Locates and decodes a QR code in an image.
56	   *
57	   * @return a String representing the content encoded by the QR code
58	   * @throws NotFoundException if a QR code cannot be found
59	   * @throws FormatException if a QR code cannot be decoded
60	   * @throws ChecksumException if error correction fails
61	   */
62	  @Override
63	  public Result decode(BinaryBitmap image) throws NotFoundException, ChecksumException, FormatException {
64	    return decode(image, null);
65	  }
66	
67	  @Override
68	  public final Result decode(BinaryBitmap image, Map<DecodeHintType,?> hints)
69	      throws NotFoundException, ChecksumException, FormatException {
70	    DecoderResult decoderResult;
71	    ResultPoint[] points;
72	    if (hints != null && hints.containsKey(DecodeHintType.PURE_BARCODE)) {
73	      BitMatrix bits = extractPureBits(image.getBlackMatrix());
74	      decoderResult = decoder.decode(bits, hints);
75	      points = NO_POINTS;
76	    } else {
77	      DetectorResult detectorResult = new Detector(image.getBlackMatrix()).detect(hints);
78	      decoderResult = decoder.decode(detectorResult.getBits(), hints);
79	      points = detectorResult.getPoints();
80	    }
81	
82	    // If the code was mirrored: swap the bottom-left and the top-right points.
83	    if (decoderResult.getOther() instanceof QRCodeDecoderMetaData) {
84	      ((QRCodeDecoderMetaData) decoderResult.getOther()).applyMirroredCorrection(points);
85	    }
86	
87	    Result result = new Result(decoderResult.getText(), decoderResult.getRawBytes(), points, BarcodeFormat.QR_CODE);
88	    List<byte[]> byteSegments = decoderResult.getByteSegments();
89	    if (byteSegments != null) {
90	      result.putMetadata(ResultMetadataType.BYTE_SEGMENTS, byteSegments);
91	    }
92	    String ecLevel = decoderResult.getECLevel();
93	    if (ecLevel != null) {
94	      result.putMetadata(ResultMetadataType.ERROR_CORRECTION_LEVEL, ecLevel);
95	    }
96	    if (decoderResult.hasStructuredAppend()) {
97	      result.putMetadata(ResultMetadataType.STRUCTURED_APPEND_SEQUENCE,
98	                         decoderResult.getStructuredAppendSequenceNumber());
99	      result.putMetadata(ResultMetadataType.STRUCTURED_APPEND_PARITY,
100	                         decoderResult.getStructuredAppendParity());
101	    }
102	    result.putMetadata(ResultMetadataType.ERRORS_CORRECTED, decoderResult.getErrorsCorrected());
103	    result.putMetadata(ResultMetadataType.SYMBOLOGY_IDENTIFIER, "]Q" + decoderResult.getSymbologyModifier());
104	    return result;
105	  }
106	
107	  @Override
108	  public void reset() {
109	    // do nothing
110	  }
111	
112	  /**
113	   * This method detects a code in a "pure" image -- that is, pure monochrome image
114	   * which contains only an unrotated, unskewed, image of a code, with some white border
115	   * around it. This is a specialized method that works exceptionally fast in this special
116	   * case.
117	   */
118	  private static BitMatrix extractPureBits(BitMatrix image) throws NotFoundException {
119	
120	    int[] leftTopBlack = image.getTopLeftOnBit();
121	    int[] rightBottomBlack = image.getBottomRightOnBit();
122	    if (leftTopBlack == null || rightBottomBlack == null) {
123	      throw NotFoundException.getNotFoundInstance();
124	    }
125	
126	    float moduleSize = moduleSize(leftTopBlack, image);
127	
128	    int top = leftTopBlack[1];
129	    int bottom = rightBottomBlack[1];
130	    int left = leftTopBlack[0];
131	    int right = rightBottomBlack[0];
132	
133	    // Sanity check!
134	    if (left >= right || top >= bottom) {
135	      throw NotFoundException.getNotFoundInstance();
136	    }
137	
138	    if (bottom - top != right - left) {
139	      // Special case, where bottom-right module wasn't black so we found something else in the last row
140	      // Assume it's a square, so use height as the width
141	      right = left + (bottom - top);
142	      if (right >= image.getWidth()) {
143	        // Abort if that would not make sense -- off image
144	        throw NotFoundException.getNotFoundInstance();
145	      }
146	    }
147	
148	    int matrixWidth = Math.round((right - left + 1) / moduleSize);
149	    int matrixHeight = Math.round((bottom - top + 1) / moduleSize);
150	    if (matrixWidth <= 0 || matrixHeight <= 0) {
151	      throw NotFoundException.getNotFoundInstance();
152	    }
153	    if (matrixHeight != matrixWidth) {
154	      // Only possibly decode square regions
155	      throw NotFoundException.getNotFoundInstance();
156	    }
157	
158	    // Push in the "border" by half the module width so that we start
159	    // sampling in the middle of the module. Just in case the image is a
160	    // little off, this will help recover.
161	    int nudge = (int) (moduleSize / 2.0f);
162	    top += nudge;
163	    left += nudge;
164	
165	    // But careful that this does not sample off the edge
166	    // "right" is the farthest-right valid pixel location -- right+1 is not necessarily
167	    // This is positive by how much the inner x loop below would be too large
168	    int nudgedTooFarRight = left + (int) ((matrixWidth - 1) * moduleSize) - right;
169	    if (nudgedTooFarRight > 0) {
170	      if (nudgedTooFarRight > nudge) {
171	        // Neither way fits; abort
172	        throw NotFoundException.getNotFoundInstance();
173	      }
174	      left -= nudgedTooFarRight;
175	    }
176	    // See logic above
177	    int nudgedTooFarDown = top + (int) ((matrixHeight - 1) * moduleSize) - bottom;
178	    if (nudgedTooFarDown > 0) {
179	      if (nudgedTooFarDown > nudge) {
180	        // Neither way fits; abort
181	        throw NotFoundException.getNotFoundInstance();
182	      }
183	      top -= nudgedTooFarDown;
184	    }
185	
186	    // Now just read off the bits
187	    BitMatrix bits = new BitMatrix(matrixWidth, matrixHeight);
188	    for (int y = 0; y < matrixHeight; y++) {
189	      int iOffset = top + (int) (y * moduleSize);
190	      for (int x = 0; x < matrixWidth; x++) {
191	        if (image.get(left + (int) (x * moduleSize), iOffset)) {
192	          bits.set(x, y);
193	        }
194	      }
195	    }
196	    return bits;
197	  }
198	
199	  private static float moduleSize(int[] leftTopBlack, BitMatrix image) throws NotFoundException {
200	    int height = image.getHeight();
201	    int width = image.getWidth();
202	    int x = leftTopBlack[0];
203	    int y = leftTopBlack[1];
204	    boolean inBlack = true;
205	    int transitions = 0;
206	    while (x < width && y < height) {
207	      if (inBlack != image.get(x, y)) {
208	        if (++transitions == 5) {
209	          break;
210	        }
211	        inBlack = !inBlack;
212	      }
213	      x++;
214	      y++;
215	    }
216	    if (x == width || y == height) {
217	      throw NotFoundException.getNotFoundInstance();
218	    }
219	    return (x - leftTopBlack[0]) / 7.0f;
220	  }
221	
222	}
