42	  /**
43	   * Renders a {@link BitMatrix} as an image, where "false" bits are rendered
44	   * as white, and "true" bits are rendered as black. Uses default configuration.
45	   *
46	   * @param matrix {@link BitMatrix} to write
47	   * @return {@link BufferedImage} representation of the input
48	   */
49	  public static BufferedImage toBufferedImage(BitMatrix matrix) {
50	    return toBufferedImage(matrix, DEFAULT_CONFIG);
51	  }
