17	package com.google.zxing.qrcode.detector;
18	
19	import com.google.zxing.DecodeHintType;
20	import com.google.zxing.NotFoundException;
21	import com.google.zxing.ResultPoint;
22	import com.google.zxing.ResultPointCallback;
23	import com.google.zxing.common.BitMatrix;
24	
25	import java.io.Serializable;
26	import java.util.ArrayList;
27	import java.util.Arrays;
28	import java.util.Collections;
29	import java.util.Comparator;
30	import java.util.Iterator;
31	import java.util.List;
32	import java.util.Map;
33	
34	/**
35	 * <p>This class attempts to find finder patterns in a QR Code. Finder patterns are the square
36	 * markers at three corners of a QR Code.</p>
37	 *
38	 * <p>This class is thread-safe but not reentrant. Each thread must allocate its own object.
39	 *
40	 * @author Sean Owen
41	 */
42	public class FinderPatternFinder {
43	
44	  private static final int CENTER_QUORUM = 2;
45	  private static final int MAX_FINDER_PATTERN_CANDIDATES = 25;
46	  private static final EstimatedModuleComparator moduleComparator = new EstimatedModuleComparator();
47	  protected static final int MIN_SKIP = 3; // 1 pixel/module times 3 modules/center
48	  protected static final int MAX_MODULES = 97; // support up to version 20 for mobile clients
49	
50	  private final BitMatrix image;
51	  private final List<FinderPattern> possibleCenters;
52	  private boolean hasSkipped;
53	  private final int[] crossCheckStateCount;
54	  private final ResultPointCallback resultPointCallback;
55	
56	  /**
57	   * <p>Creates a finder that will search the image for three finder patterns.</p>
58	   *
59	   * @param image image to search
60	   */
61	  public FinderPatternFinder(BitMatrix image) {
62	    this(image, null);
63	  }
64	
65	  public FinderPatternFinder(BitMatrix image, ResultPointCallback resultPointCallback) {
66	    this.image = image;
67	    this.possibleCenters = new ArrayList<>();
68	    this.crossCheckStateCount = new int[5];
69	    this.resultPointCallback = resultPointCallback;
70	  }
71	
72	  protected final BitMatrix getImage() {
73	    return image;
74	  }
75	
76	  protected final List<FinderPattern> getPossibleCenters() {
77	    return possibleCenters;
78	  }
79	
80	  final FinderPatternInfo find(Map<DecodeHintType,?> hints) throws NotFoundException {
81	    boolean tryHarder = hints != null && hints.containsKey(DecodeHintType.TRY_HARDER);
82	    int maxI = image.getHeight();
83	    int maxJ = image.getWidth();
84	    // We are looking for black/white/black/white/black modules in
85	    // 1:1:3:1:1 ratio; this tracks the number of such modules seen so far
86	
87	    // Let's assume that the maximum version QR Code we support takes up 1/4 the height of the
88	    // image, and then account for the center being 3 modules in size. This gives the smallest
89	    // number of pixels the center could be, so skip this often. When trying harder, look for all
90	    // QR versions regardless of how dense they are.
91	    int iSkip = (3 * maxI) / (4 * MAX_MODULES);
92	    if (iSkip < MIN_SKIP || tryHarder) {
93	      iSkip = MIN_SKIP;
94	    }
95	
96	    boolean done = false;
97	    int[] stateCount = new int[5];
98	    for (int i = iSkip - 1; i < maxI && !done; i += iSkip) {
99	      // Get a row of black/white values
100	      doClearCounts(stateCount);
101	      int currentState = 0;
102	      for (int j = 0; j < maxJ; j++) {
103	        if (image.get(j, i)) {
104	          // Black pixel
105	          if ((currentState & 1) == 1) { // Counting white pixels
106	            currentState++;
107	          }
108	          stateCount[currentState]++;
109	        } else { // White pixel
110	          if ((currentState & 1) == 0) { // Counting black pixels
111	            if (currentState == 4) { // A winner?
112	              if (foundPatternCross(stateCount)) { // Yes
113	                boolean confirmed = handlePossibleCenter(stateCount, i, j);
114	                if (confirmed) {
115	                  // Start examining every other line. Checking each line turned out to be too
116	                  // expensive and didn't improve performance.
117	                  iSkip = 2;
118	                  if (hasSkipped) {
119	                    done = haveMultiplyConfirmedCenters();
120	                  } else {
121	                    int rowSkip = findRowSkip();
122	                    if (rowSkip > stateCount[2]) {
123	                      // Skip rows between row of lower confirmed center
124	                      // and top of presumed third confirmed center
125	                      // but back up a bit to get a full chance of detecting
126	                      // it, entire width of center of finder pattern
127	
128	                      // Skip by rowSkip, but back off by stateCount[2] (size of last center
129	                      // of pattern we saw) to be conservative, and also back off by iSkip which
130	                      // is about to be re-added
131	                      i += rowSkip - stateCount[2] - iSkip;
132	                      j = maxJ - 1;
133	                    }
134	                  }
135	                } else {
136	                  doShiftCounts2(stateCount);
137	                  currentState = 3;
138	                  continue;
139	                }
140	                // Clear state to start looking again
141	                currentState = 0;
142	                doClearCounts(stateCount);
143	              } else { // No, shift counts back by two
144	                doShiftCounts2(stateCount);
145	                currentState = 3;
146	              }
147	            } else {
148	              stateCount[++currentState]++;
149	            }
150	          } else { // Counting white pixels
151	            stateCount[currentState]++;
152	          }
153	        }
154	      }
155	      if (foundPatternCross(stateCount)) {
156	        boolean confirmed = handlePossibleCenter(stateCount, i, maxJ);
157	        if (confirmed) {
158	          iSkip = stateCount[0];
159	          if (hasSkipped) {
160	            // Found a third one
161	            done = haveMultiplyConfirmedCenters();
162	          }
163	        }
164	      }
165	    }
166	
167	    FinderPattern[] patternInfo = selectBestPatterns();
168	    ResultPoint.orderBestPatterns(patternInfo);
169	
170	    return new FinderPatternInfo(patternInfo);
171	  }
172	
173	  /**
174	   * Given a count of black/white/black/white/black pixels just seen and an end position,
175	   * figures the location of the center of this run.
176	   */
177	  private static float centerFromEnd(int[] stateCount, int end) {
178	    return (end - stateCount[4] - stateCount[3]) - stateCount[2] / 2.0f;
179	  }
180	
181	  /**
182	   * @param stateCount count of black/white/black/white/black pixels just read
183	   * @return true iff the proportions of the counts is close enough to the 1/1/3/1/1 ratios
184	   *         used by finder patterns to be considered a match
185	   */
186	  protected static boolean foundPatternCross(int[] stateCount) {
187	    int totalModuleSize = 0;
188	    for (int i = 0; i < 5; i++) {
189	      int count = stateCount[i];
190	      if (count == 0) {
191	        return false;
192	      }
193	      totalModuleSize += count;
194	    }
195	    if (totalModuleSize < 7) {
196	      return false;
197	    }
198	    float moduleSize = totalModuleSize / 7.0f;
199	    float maxVariance = moduleSize / 2.0f;
200	    // Allow less than 50% variance from 1-1-3-1-1 proportions
201	    return
202	        Math.abs(moduleSize - stateCount[0]) < maxVariance &&
203	        Math.abs(moduleSize - stateCount[1]) < maxVariance &&
204	        Math.abs(3.0f * moduleSize - stateCount[2]) < 3 * maxVariance &&
205	        Math.abs(moduleSize - stateCount[3]) < maxVariance &&
206	        Math.abs(moduleSize - stateCount[4]) < maxVariance;
207	  }
208	
209	  /**
210	   * @param stateCount count of black/white/black/white/black pixels just read
211	   * @return true iff the proportions of the counts is close enough to the 1/1/3/1/1 ratios
212	   *         used by finder patterns to be considered a match
213	   */
214	  protected static boolean foundPatternDiagonal(int[] stateCount) {
215	    int totalModuleSize = 0;
216	    for (int i = 0; i < 5; i++) {
217	      int count = stateCount[i];
218	      if (count == 0) {
219	        return false;
220	      }
221	      totalModuleSize += count;
222	    }
223	    if (totalModuleSize < 7) {
224	      return false;
225	    }
226	    float moduleSize = totalModuleSize / 7.0f;
227	    float maxVariance = moduleSize / 1.333f;
228	    // Allow less than 75% variance from 1-1-3-1-1 proportions
229	    return
230	            Math.abs(moduleSize - stateCount[0]) < maxVariance &&
231	                    Math.abs(moduleSize - stateCount[1]) < maxVariance &&
232	                    Math.abs(3.0f * moduleSize - stateCount[2]) < 3 * maxVariance &&
233	                    Math.abs(moduleSize - stateCount[3]) < maxVariance &&
234	                    Math.abs(moduleSize - stateCount[4]) < maxVariance;
235	  }
236	
237	  private int[] getCrossCheckStateCount() {
238	    doClearCounts(crossCheckStateCount);
239	    return crossCheckStateCount;
240	  }
241	
242	  @Deprecated
243	  protected final void clearCounts(int[] counts) {
244	    doClearCounts(counts);
245	  }
246	
247	  @Deprecated
248	  protected final void shiftCounts2(int[] stateCount) {
249	    doShiftCounts2(stateCount);
250	  }
251	
252	  protected static void doClearCounts(int[] counts) {
253	    Arrays.fill(counts, 0);
254	  }
255	
256	  protected static void doShiftCounts2(int[] stateCount) {
257	    stateCount[0] = stateCount[2];
258	    stateCount[1] = stateCount[3];
259	    stateCount[2] = stateCount[4];
260	    stateCount[3] = 1;
261	    stateCount[4] = 0;
262	  }
263	
264	  /**
265	   * After a vertical and horizontal scan finds a potential finder pattern, this method
266	   * "cross-cross-cross-checks" by scanning down diagonally through the center of the possible
267	   * finder pattern to see if the same proportion is detected.
268	   *
269	   * @param centerI row where a finder pattern was detected
270	   * @param centerJ center of the section that appears to cross a finder pattern
271	   * @return true if proportions are withing expected limits
272	   */
273	  private boolean crossCheckDiagonal(int centerI, int centerJ) {
274	    int[] stateCount = getCrossCheckStateCount();
275	
276	    // Start counting up, left from center finding black center mass
277	    int i = 0;
278	    while (centerI >= i && centerJ >= i && image.get(centerJ - i, centerI - i)) {
279	      stateCount[2]++;
280	      i++;
281	    }
282	    if (stateCount[2] == 0) {
283	      return false;
284	    }
285	
286	    // Continue up, left finding white space
287	    while (centerI >= i && centerJ >= i && !image.get(centerJ - i, centerI - i)) {
288	      stateCount[1]++;
289	      i++;
290	    }
291	    if (stateCount[1] == 0) {
292	      return false;
293	    }
294	
295	    // Continue up, left finding black border
296	    while (centerI >= i && centerJ >= i && image.get(centerJ - i, centerI - i)) {
297	      stateCount[0]++;
298	      i++;
299	    }
300	    if (stateCount[0] == 0) {
301	      return false;
302	    }
303	
304	    int maxI = image.getHeight();
305	    int maxJ = image.getWidth();
306	
307	    // Now also count down, right from center
308	    i = 1;
309	    while (centerI + i < maxI && centerJ + i < maxJ && image.get(centerJ + i, centerI + i)) {
310	      stateCount[2]++;
311	      i++;
312	    }
313	
314	    while (centerI + i < maxI && centerJ + i < maxJ && !image.get(centerJ + i, centerI + i)) {
315	      stateCount[3]++;
316	      i++;
317	    }
318	    if (stateCount[3] == 0) {
319	      return false;
320	    }
321	
322	    while (centerI + i < maxI && centerJ + i < maxJ && image.get(centerJ + i, centerI + i)) {
323	      stateCount[4]++;
324	      i++;
325	    }
326	    if (stateCount[4] == 0) {
327	      return false;
328	    }
329	
330	    return foundPatternDiagonal(stateCount);
331	  }
332	
333	  /**
334	   * <p>After a horizontal scan finds a potential finder pattern, this method
335	   * "cross-checks" by scanning down vertically through the center of the possible
336	   * finder pattern to see if the same proportion is detected.</p>
337	   *
338	   * @param startI row where a finder pattern was detected
339	   * @param centerJ center of the section that appears to cross a finder pattern
340	   * @param maxCount maximum reasonable number of modules that should be
341	   * observed in any reading state, based on the results of the horizontal scan
342	   * @return vertical center of finder pattern, or {@link Float#NaN} if not found
343	   */
344	  private float crossCheckVertical(int startI, int centerJ, int maxCount,
345	      int originalStateCountTotal) {
346	    BitMatrix image = this.image;
347	
348	    int maxI = image.getHeight();
349	    int[] stateCount = getCrossCheckStateCount();
350	
351	    // Start counting up from center
352	    int i = startI;
353	    while (i >= 0 && image.get(centerJ, i)) {
354	      stateCount[2]++;
355	      i--;
356	    }
357	    if (i < 0) {
358	      return Float.NaN;
359	    }
360	    while (i >= 0 && !image.get(centerJ, i) && stateCount[1] <= maxCount) {
361	      stateCount[1]++;
362	      i--;
363	    }
364	    // If already too many modules in this state or ran off the edge:
365	    if (i < 0 || stateCount[1] > maxCount) {
366	      return Float.NaN;
367	    }
368	    while (i >= 0 && image.get(centerJ, i) && stateCount[0] <= maxCount) {
369	      stateCount[0]++;
370	      i--;
371	    }
372	    if (stateCount[0] > maxCount) {
373	      return Float.NaN;
374	    }
375	
376	    // Now also count down from center
377	    i = startI + 1;
378	    while (i < maxI && image.get(centerJ, i)) {
379	      stateCount[2]++;
380	      i++;
381	    }
382	    if (i == maxI) {
383	      return Float.NaN;
384	    }
385	    while (i < maxI && !image.get(centerJ, i) && stateCount[3] < maxCount) {
386	      stateCount[3]++;
387	      i++;
388	    }
389	    if (i == maxI || stateCount[3] >= maxCount) {
390	      return Float.NaN;
391	    }
392	    while (i < maxI && image.get(centerJ, i) && stateCount[4] < maxCount) {
393	      stateCount[4]++;
394	      i++;
395	    }
396	    if (stateCount[4] >= maxCount) {
397	      return Float.NaN;
398	    }
399	
400	    // If we found a finder-pattern-like section, but its size is more than 40% different than
401	    // the original, assume it's a false positive
402	    int stateCountTotal = stateCount[0] + stateCount[1] + stateCount[2] + stateCount[3] +
403	        stateCount[4];
404	    if (5 * Math.abs(stateCountTotal - originalStateCountTotal) >= 2 * originalStateCountTotal) {
405	      return Float.NaN;
406	    }
407	
408	    return foundPatternCross(stateCount) ? centerFromEnd(stateCount, i) : Float.NaN;
409	  }
