413	   * except it reads horizontally instead of vertically. This is used to cross-cross
414	   * check a vertical cross check and locate the real center of the alignment pattern.</p>
415	   */
416	  private float crossCheckHorizontal(int startJ, int centerI, int maxCount,
417	      int originalStateCountTotal) {
418	    BitMatrix image = this.image;
419	
420	    int maxJ = image.getWidth();
421	    int[] stateCount = getCrossCheckStateCount();
422	
423	    int j = startJ;
424	    while (j >= 0 && image.get(j, centerI)) {
425	      stateCount[2]++;
426	      j--;
427	    }
428	    if (j < 0) {
429	      return Float.NaN;
430	    }
431	    while (j >= 0 && !image.get(j, centerI) && stateCount[1] <= maxCount) {
432	      stateCount[1]++;
433	      j--;
434	    }
435	    if (j < 0 || stateCount[1] > maxCount) {
436	      return Float.NaN;
437	    }
438	    while (j >= 0 && image.get(j, centerI) && stateCount[0] <= maxCount) {
439	      stateCount[0]++;
440	      j--;
441	    }
442	    if (stateCount[0] > maxCount) {
443	      return Float.NaN;
444	    }
445	
446	    j = startJ + 1;
447	    while (j < maxJ && image.get(j, centerI)) {
448	      stateCount[2]++;
449	      j++;
450	    }
451	    if (j == maxJ) {
452	      return Float.NaN;
453	    }
454	    while (j < maxJ && !image.get(j, centerI) && stateCount[3] < maxCount) {
455	      stateCount[3]++;
456	      j++;
457	    }
458	    if (j == maxJ || stateCount[3] >= maxCount) {
459	      return Float.NaN;
460	    }
461	    while (j < maxJ && image.get(j, centerI) && stateCount[4] < maxCount) {
462	      stateCount[4]++;
463	      j++;
464	    }
465	    if (stateCount[4] >= maxCount) {
466	      return Float.NaN;
467	    }
468	
469	    // If we found a finder-pattern-like section, but its size is significantly different than
470	    // the original, assume it's a false positive
471	    int stateCountTotal = stateCount[0] + stateCount[1] + stateCount[2] + stateCount[3] +
472	        stateCount[4];
473	    if (5 * Math.abs(stateCountTotal - originalStateCountTotal) >= originalStateCountTotal) {
474	      return Float.NaN;
475	    }
476	
477	    return foundPatternCross(stateCount) ? centerFromEnd(stateCount, j) : Float.NaN;
