494	  /**
495	   * <p>This is called when a horizontal scan finds a possible alignment pattern. It will
496	   * cross check with a vertical scan, and if successful, will, ah, cross-cross-check
497	   * with another horizontal scan. This is needed primarily to locate the real horizontal
498	   * center of the pattern in cases of extreme skew.
499	   * And then we cross-cross-cross check with another diagonal scan.</p>
500	   *
501	   * <p>If that succeeds the finder pattern location is added to a list that tracks
502	   * the number of times each location has been nearly-matched as a finder pattern.
503	   * Each additional find is more evidence that the location is in fact a finder
504	   * pattern center
505	   *
506	   * @param stateCount reading state module counts from horizontal scan
507	   * @param i row where finder pattern may be found
508	   * @param j end of possible finder pattern in row
509	   * @return true if a finder pattern candidate was found this time
510	   */
511	  protected final boolean handlePossibleCenter(int[] stateCount, int i, int j) {
512	    int stateCountTotal = stateCount[0] + stateCount[1] + stateCount[2] + stateCount[3] +
513	        stateCount[4];
514	    float centerJ = centerFromEnd(stateCount, j);
515	    float centerI = crossCheckVertical(i, (int) centerJ, stateCount[2], stateCountTotal);
516	    if (!Float.isNaN(centerI)) {
517	      // Re-cross check
518	      centerJ = crossCheckHorizontal((int) centerJ, (int) centerI, stateCount[2], stateCountTotal);
519	      if (!Float.isNaN(centerJ) && crossCheckDiagonal((int) centerI, (int) centerJ)) {
520	        float estimatedModuleSize = stateCountTotal / 7.0f;
521	        boolean found = false;
522	        for (int index = 0; index < possibleCenters.size(); index++) {
523	          FinderPattern center = possibleCenters.get(index);
524	          // Look for about the same center and module size:
525	          if (center.aboutEquals(estimatedModuleSize, centerI, centerJ)) {
526	            possibleCenters.set(index, center.combineEstimate(centerI, centerJ, estimatedModuleSize));
527	            found = true;
528	            break;
529	          }
530	        }
531	        if (!found) {
532	          FinderPattern point = new FinderPattern(centerJ, centerI, estimatedModuleSize);
533	          possibleCenters.add(point);
534	          if (resultPointCallback != null) {
535	            resultPointCallback.foundPossibleResultPoint(point);
536	          }
537	        }
538	        return true;
539	      }
540	    }
541	    return false;
542	  }
