544	  /**
545	   * @return number of rows we could safely skip during scanning, based on the first
546	   *         two finder patterns that have been located. In some cases their position will
547	   *         allow us to infer that the third pattern must lie below a certain point farther
548	   *         down in the image.
549	   */
550	  private int findRowSkip() {
551	    int max = possibleCenters.size();
552	    if (max <= 1) {
553	      return 0;
554	    }
555	    ResultPoint firstConfirmedCenter = null;
556	    for (FinderPattern center : possibleCenters) {
557	      if (center.getCount() >= CENTER_QUORUM) {
558	        if (firstConfirmedCenter == null) {
559	          firstConfirmedCenter = center;
560	        } else {
561	          // We have two confirmed centers
562	          // How far down can we skip before resuming looking for the next
563	          // pattern? In the worst case, only the difference between the
564	          // difference in the x / y coordinates of the two centers.
565	          // This is the case where you find top left last.
566	          hasSkipped = true;
567	          return (int) (Math.abs(firstConfirmedCenter.getX() - center.getX()) -
568	              Math.abs(firstConfirmedCenter.getY() - center.getY())) / 2;
569	        }
570	      }
571	    }
572	    return 0;
573	  }
