575	  /**
576	   * @return true iff we have found at least 3 finder patterns that have been detected
577	   *         at least {@link #CENTER_QUORUM} times each, and, the estimated module size of the
578	   *         candidates is "pretty similar"
579	   */
580	  private boolean haveMultiplyConfirmedCenters() {
581	    int confirmedCount = 0;
582	    float totalModuleSize = 0.0f;
583	    int max = possibleCenters.size();
584	    for (FinderPattern pattern : possibleCenters) {
585	      if (pattern.getCount() >= CENTER_QUORUM) {
586	        confirmedCount++;
587	        totalModuleSize += pattern.getEstimatedModuleSize();
588	      }
589	    }
590	    if (confirmedCount < 3) {
591	      return false;
592	    }
593	    // OK, we have at least 3 confirmed centers, but, it's possible that one is a "false positive"
594	    // and that we need to keep looking. We detect this by asking if the estimated module sizes
595	    // vary too much. We arbitrarily say that when the total deviation from average exceeds
596	    // 5% of the total module size estimates, it's too much.
597	    float average = totalModuleSize / max;
598	    float totalDeviation = 0.0f;
599	    for (FinderPattern pattern : possibleCenters) {
600	      totalDeviation += Math.abs(pattern.getEstimatedModuleSize() - average);
601	    }
602	    return totalDeviation <= 0.05f * totalModuleSize;
603	  }
