605	  /**
606	   * Get square of distance between a and b.
607	   */
608	  private static double squaredDistance(FinderPattern a, FinderPattern b) {
609	    double x = a.getX() - b.getX();
610	    double y = a.getY() - b.getY();
611	    return x * x + y * y;
612	  }
