614	  /**
615	   * @return the 3 best {@link FinderPattern}s from our list of candidates. The "best" are
616	   *         those have similar module size and form a shape closer to a isosceles right triangle.
617	   * @throws NotFoundException if 3 such finder patterns do not exist
618	   */
619	  private FinderPattern[] selectBestPatterns() throws NotFoundException {
620	
621	    int startSize = possibleCenters.size();
622	    if (startSize < 3) {
623	      // Couldn't find enough finder patterns
624	      throw NotFoundException.getNotFoundInstance();
625	    }
626	
627	    int confirmedCount = 0;
628	    for (FinderPattern pattern : possibleCenters) {
629	      if (pattern.getCount() >= CENTER_QUORUM) {
630	        confirmedCount++;
631	      }
632	    }
633	    if (confirmedCount >= 3 || startSize > MAX_FINDER_PATTERN_CANDIDATES) {
634	      for (Iterator<FinderPattern> it = possibleCenters.iterator(); it.hasNext();) {
635	        if (it.next().getCount() < CENTER_QUORUM) {
636	          it.remove();
637	        }
638	      }
639	    }
640	
641	    // A more up-to-date version would be "possibleCenters.sort(moduleComparator);"
642	    // But we need this old syntax for android API 23 (Marshmallow) and below
643	    // cf. https://github.com/zxing/zxing/issues/1358
644	    Collections.sort(possibleCenters, moduleComparator);
645	
646	    double distortion = Double.MAX_VALUE;
647	    FinderPattern[] bestPatterns = new FinderPattern[3];
648	
649	    for (int i = 0; i < possibleCenters.size() - 2; i++) {
650	      FinderPattern fpi = possibleCenters.get(i);
651	      float minModuleSize = fpi.getEstimatedModuleSize();
652	
653	      for (int j = i + 1; j < possibleCenters.size() - 1; j++) {
654	        FinderPattern fpj = possibleCenters.get(j);
655	        double squares0 = squaredDistance(fpi, fpj);
656	
657	        for (int k = j + 1; k < possibleCenters.size(); k++) {
658	          FinderPattern fpk = possibleCenters.get(k);
659	          float maxModuleSize = fpk.getEstimatedModuleSize();
660	          if (maxModuleSize > minModuleSize * 1.4f) {
661	            // module size is not similar
662	            continue;
663	          }
664	
665	          double a = squares0;
666	          double b = squaredDistance(fpj, fpk);
667	          double c = squaredDistance(fpi, fpk);
668	
669	          // sorts ascending - inlined
670	          if (a < b) {
671	            if (b > c) {
672	              if (a < c) {
673	                double temp = b;
674	                b = c;
675	                c = temp;
676	              } else {
677	                double temp = a;
678	                a = c;
679	                c = b;
680	                b = temp;
681	              }
682	            }
683	          } else {
684	            if (b < c) {
685	              if (a < c) {
686	                double temp = a;
687	                a = b;
688	                b = temp;
689	              } else {
690	                double temp = a;
691	                a = b;
692	                b = c;
693	                c = temp;
694	              }
695	            } else {
696	              double temp = a;
697	              a = c;
698	              c = temp;
699	            }
700	          }
701	
702	          // a^2 + b^2 = c^2 (Pythagorean theorem), and a = b (isosceles triangle).
703	          // Since any right triangle satisfies the formula c^2 - b^2 - a^2 = 0,
704	          // we need to check both two equal sides separately.
705	          // The value of |c^2 - 2 * b^2| + |c^2 - 2 * a^2| increases as dissimilarity
706	          // from isosceles right triangle.
707	          // Heuristically it seems that the following formula works better (although it's
708	          // not clear any more why...)
709	          double d = Math.abs(c - 2 * b) + Math.abs(c - 2 * a);
710	          if (d < distortion) {
711	            distortion = d;
712	            bestPatterns[0] = fpi;
713	            bestPatterns[1] = fpj;
714	            bestPatterns[2] = fpk;
715	          }
716	        }
717	      }
718	    }
719	
720	    if (distortion == Double.MAX_VALUE) {
721	      throw NotFoundException.getNotFoundInstance();
722	    }
723	
724	    return bestPatterns;
725	  }
