      // from isosceles right triangle.
      // Heuristically it seems that the following formula works better (although it's
      // not clear any more why...)
      double d = Math.abs(c - 2 * b) + Math.abs(c - 2 * a);
      if (d < distortion) {
        distortion = d;
        bestPatterns[0] = fpi;
        bestPatterns[1] = fpj;
        bestPatterns[2] = fpk;
      }
    }
  }
